package app.vibefinancier;

import android.app.*;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

/** A dedicated operation layout with the calculator always within reach. */
public final class OperationScreen extends LinearLayout {
    private final Activity activity;private final Spinner account,category,to,subcategory;private final List<JSONObject> accounts,roots,children,categories;private final String kind;private final LinearLayout route;private final FlowLayout chips;private final EditText amount;private final TextView result;
    public OperationScreen(Activity a,Store store,boolean owned,String kind,LinearLayout fields,EditText amount,LinearLayout dateRow,Spinner account,Spinner category,Spinner to,Spinner subcategory,List<JSONObject> accounts,List<JSONObject> roots,List<JSONObject> children,List<JSONObject> categories){
        super(a);this.activity=a;this.kind=kind;this.amount=amount;this.account=account;this.category=category;this.to=to;this.subcategory=subcategory;this.accounts=accounts;this.roots=roots;this.children=children;this.categories=categories;setOrientation(VERTICAL);setBackgroundColor(Ui.BG);
        route=new LinearLayout(a);route.setGravity(Gravity.CENTER_VERTICAL);route.setPadding(Ui.dp(a,12),Ui.dp(a,6),Ui.dp(a,12),Ui.dp(a,6));addView(route,new LayoutParams(-1,Ui.dp(a,72)));
        hideWithLabel(fields,account);if(category!=null)hideWithLabel(fields,category);if(to!=null)hideWithLabel(fields,to);if(subcategory!=null)hideWithLabel(fields,subcategory);
        View label=fields.getChildAt(fields.indexOfChild(amount)-1);fields.removeView(label);fields.removeView(amount);fields.removeView(dateRow);amount.setTextSize(38);amount.setGravity(Gravity.CENTER);amount.setShowSoftInputOnFocus(false);amount.setBackgroundColor(Ui.SURFACE);amount.setPadding(Ui.dp(a,8),0,Ui.dp(a,8),0);addView(amount,new LayoutParams(-1,Ui.dp(a,66)));
        result=Ui.text(a,"",11,Ui.MUTED);result.setGravity(Gravity.CENTER);addView(result);
        // The compact form retains its popup calculator; this screen has its own keypad.
        for(int i=fields.getChildCount()-1;i>=0;i--){View child=fields.getChildAt(i);if(child instanceof Button b&&b.getText().toString().equals(Strings.t(a,"Calculator")))fields.removeView(child);}
        chips=new FlowLayout(a);if(category!=null){LinearLayout choice=new LinearLayout(a);choice.setOrientation(VERTICAL);choice.addView(Ui.text(a,"Subcategories",13,Ui.MUTED));choice.addView(chips);choice.addView(Ui.button(a,"Create subcategory",()->{
            if(roots.isEmpty()){Ui.message(a,"Category required","Create a parent category from the main menu first.");return;}LinearLayout box=Ui.column(a);EditText name=Ui.field(a,box,"Name","",false);AlertDialog dialog=new LocalizedDialog(a).setTitle("New subcategory").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Create",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{try{if(Ui.value(name).isEmpty())throw new IllegalArgumentException("Enter a name.");JSONObject p=Ledger.obj("id",UUID.randomUUID().toString(),"entity","category","name",Ui.value(name),"direction",kind,"parent",roots.get(category.getSelectedItemPosition()).optString("id"));store.edit(p);categories.add(p);select(category,category.getSelectedItemPosition());for(int i=0;i<children.size();i++)if(children.get(i).optString("id").equals(p.optString("id")))subcategory.setSelection(i+1);refresh();if(owned)SyncWorker.enqueue(a);dialog.dismiss();}catch(Exception e){name.setError(e.getMessage());}}));dialog.show();}));fields.addView(choice,0);}
        addView(Ui.scroll(a,fields),new LayoutParams(-1,0,1));
        String[][] keys={{"C","(",")","÷"},{"1","2","3","×"},{"4","5","6","−"},{"7","8","9","+"},{".","0","⌫","="}};
        for(String[] row:keys){LinearLayout line=new LinearLayout(a);for(String key:row){TextView button=Ui.text(a,key,24,key.equals("=")?Ui.GREEN:key.equals("C")||key.equals("⌫")?0xffed7474:Ui.INK);button.setGravity(Gravity.CENTER);button.setFocusable(true);button.setContentDescription(key);button.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf(Ui.DIVIDER),new android.graphics.drawable.ColorDrawable(Ui.BG),null));button.setOnClickListener(v->{String text=Ui.value(amount);if(key.equals("C"))amount.setText(Strings.t(activity,""));else if(key.equals("⌫"))amount.setText(text.isEmpty()?"":text.substring(0,text.length()-1));else if(key.equals("=")){try{amount.setText(Calculator.evaluate(text,Money.scale(accounts.get(account.getSelectedItemPosition()).optString("currency"))));}catch(Exception e){result.setText(e.getMessage());}}else amount.setText(text+key);amount.setSelection(amount.length());refreshResult();});line.addView(button,new LayoutParams(0,Ui.dp(a,44),1));}addView(line);}
        addView(dateRow);setMinimumHeight(a.getResources().getDisplayMetrics().heightPixels-Ui.dp(a,150));refresh();amount.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){refreshResult();}public void afterTextChanged(android.text.Editable e){}});
    }
    private static void hideWithLabel(LinearLayout fields,View field){int index=fields.indexOfChild(field);if(index>0)fields.getChildAt(index-1).setVisibility(GONE);field.setVisibility(GONE);}
    private static void select(Spinner spinner,int index){spinner.setSelection(index);if(spinner.getOnItemSelectedListener()!=null)spinner.getOnItemSelectedListener().onItemSelected(spinner,null,index,index);}
    public void refresh(){route.removeAllViews();JSONObject a=accounts.get(account.getSelectedItemPosition()),b=to!=null?accounts.get(to.getSelectedItemPosition()):roots.isEmpty()?Ledger.obj("name","Uncategorized","entity","category"):roots.get(category.getSelectedItemPosition());
        Runnable chooseAccount=()->new LocalizedDialog(activity).setTitle("Account").setItems(Ui.labels(accounts).toArray(new String[0]),(d,w)->{select(account,w);refresh();}).show();Runnable chooseOther=()->{if(to!=null)new LocalizedDialog(activity).setTitle("To account").setItems(Ui.labels(accounts).toArray(new String[0]),(d,w)->{select(to,w);refresh();}).show();else new LocalizedDialog(activity).setTitle("Category").setItems(Ui.labels(roots).toArray(new String[0]),(d,w)->{select(category,w);refresh();}).show();};
        if(kind.equals("income")){endpoint(b,"Income",chooseOther);arrow();endpoint(a,"Account",chooseAccount);}else{endpoint(a,"Account",chooseAccount);arrow();endpoint(b,to==null?"Expense":"To account",chooseOther);}
        chips.removeAllViews();if(subcategory!=null){chip("None",0);for(int i=0;i<children.size();i++)chip(children.get(i).optString("name"),i+1);}refreshResult();
    }
    private void chip(String text,int index){Button chip=Ui.button(activity,text,()->{subcategory.setSelection(index);refresh();});chip.setTextSize(13);chip.setMinWidth(0);chip.setPadding(Ui.dp(activity,10),0,Ui.dp(activity,10),0);if(subcategory.getSelectedItemPosition()==index)chip.setTextColor(Ui.INK);chips.addView(chip,new ViewGroup.LayoutParams(-2,Ui.dp(activity,44)));}
    private void endpoint(JSONObject p,String subtitle,Runnable choose){LinearLayout cell=new LinearLayout(activity);cell.setGravity(Gravity.CENTER_VERTICAL);cell.addView(new CircleIcon(activity,IconCatalog.resolve(p),IconCatalog.color(p)),new LayoutParams(Ui.dp(activity,35),Ui.dp(activity,35)));TextView name=Ui.rawText(activity,p.optString("name")+"\n"+Strings.t(activity,subtitle),14,Ui.INK);name.setMaxLines(2);name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setPadding(Ui.dp(activity,8),0,0,0);cell.addView(name,new LayoutParams(0,-2,1));cell.setOnClickListener(v->choose.run());cell.setContentDescription(p.optString("name")+", choose "+subtitle);route.addView(cell,new LayoutParams(0,-1,1));}
    private void arrow(){TextView arrow=Ui.text(activity,"›",24,Ui.MUTED);route.addView(arrow,new LayoutParams(Ui.dp(activity,24),-2));}
    private void refreshResult(){try{String currency=accounts.get(account.getSelectedItemPosition()).optString("currency");result.setText((Ui.value(amount).isEmpty()?"0":Calculator.evaluate(Ui.value(amount),Money.scale(currency)))+" "+currency);}catch(Exception e){result.setText(Strings.t(activity,"Finish the expression"));}}
}
